import React,{useState} from 'react';import{createRoot}from'react-dom/client';import{SocialProvider}from'../../../src/social/SocialContext';import Discovery from'../../../src/social/Discovery';import JournalView from'../../../src/JournalView';const defaultProfile={name:'Marie',styles:['Witchy'],shape:'Amande',length:'Moyen'};
