let posts=Array.from({length:22},(_,i)=>({id:'demo-'+i,kind:i%2?'inspiration':'journal',title:i%2?'Rose cassis céleste':'Witchy violet',handle:'atelier.camille',profileType:'pro',tags:{moods:['Witchy','Celestial'],colors:['Violet']},preview,saved:false}));
const client={auth:{getSession:async()=>({data:{session:null}})},from(table){const q={select(){return q},eq(){return q},is(){return q},order(){return q},limit(){return q},single(){return q},then(resolve){return Promise.resolve({data:table==='profiles'?{username:'marie'}:[],count:0}).then(resolve)}};return q},async rpc(name,{p_action,p_data={}}={}){if(name==='nm_social')return{data:[]};if(name==='get_public_profile')return{data:{displayName:'Atelier Camille',handle:'atelier.camille',accountType:'independent',journal:[],inspirations:[]}};if(p_action==='detail')return{data:posts.find(x=>x.id===p_data.id)};if(p_action==='add'||p_action==='remove'){posts=posts.map(x=>x.id===p_data.id?{...x,saved:p_action==='add'}:x);return{data:{ok:true}}}const filtered=posts.filter(x=>(p_action!=='favorites'||x.saved)&&(!p_data.filters?.colors||x.tags.colors.includes(p_data.filters.colors))&&(!p_data.query||x.title.toLowerCase().includes(p_data.query.toLowerCase())));return{data:{items:filtered.slice(p_data.offset||0,(p_data.offset||0)+20),hasMore:filtered.length>(p_data.offset||0)+20}}}};
